targets.rawSql:
SELECT sum(total_tokens) AS v FROM agents.usage_event WHERE $__timeFilter(ts) AND machine = ANY(ARRAY[${machine:sqlstring}]::text[])
AND agent = ANY(ARRAY[${agent:sqlstring}]::text[])
AND coalesce(model,'unknown') = ANY(ARRAY[${model:sqlstring}]::text[]);

SELECT sum(output_tokens) AS v FROM agents.usage_event WHERE $__timeFilter(ts) AND machine = ANY(ARRAY[${machine:sqlstring}]::text[])
AND agent = ANY(ARRAY[${agent:sqlstring}]::text[])
AND coalesce(model,'unknown') = ANY(ARRAY[${model:sqlstring}]::text[]);

SELECT count(*) FILTER (WHERE kind = 'agent') AS v FROM agents.usage_event WHERE $__timeFilter(ts) AND machine = ANY(ARRAY[${machine:sqlstring}]::text[])
AND agent = ANY(ARRAY[${agent:sqlstring}]::text[])
AND coalesce(model,'unknown') = ANY(ARRAY[${model:sqlstring}]::text[]);

SELECT count(DISTINCT time_bucket('1 day', ts, current_setting('TimeZone'))) AS v FROM agents.usage_event WHERE $__timeFilter(ts) AND machine = ANY(ARRAY[${machine:sqlstring}]::text[])
AND agent = ANY(ARRAY[${agent:sqlstring}]::text[])
AND coalesce(model,'unknown') = ANY(ARRAY[${model:sqlstring}]::text[]);
